<?php
declare(strict_types=1);
session_start();

/*
 DBTool v3.1
 - No SQLite/PDO SQLite dependency.
 - Configuration is stored in data/config.php as an encrypted PHP array.
 - Passwords are encrypted with dbtool.key.
 - Web login users, DB servers, databases, tables, rows, events, triggers,
   scheduler, sessions, DB accounts and statistics are managed from the UI.
 - MySQL/MariaDB: full DB account/event/trigger UI.
 - SQL Server: DB account UI uses documented T-SQL templates; session/statistics supported.
*/
const DATA_DIR=__DIR__.'/data';
const CONFIG_FILE=DATA_DIR.'/config.php';
const KEY_FILE=__DIR__.'/dbtool.key';

if(!is_dir(DATA_DIR)) @mkdir(DATA_DIR,0700,true);
if(!file_exists(KEY_FILE)){
    file_put_contents(KEY_FILE,base64_encode(random_bytes(SODIUM_CRYPTO_SECRETBOX_KEYBYTES)),LOCK_EX);
    @chmod(KEY_FILE,0600);
}
$key=base64_decode((string)file_get_contents(KEY_FILE),true);
if($key===false || strlen($key)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES) die('dbtool.key 오류');

function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function enc(string $s):string{$n=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return base64_encode($n.sodium_crypto_secretbox($s,$n,$GLOBALS['key']));}
function dec(string $s):string{$b=base64_decode($s,true);if($b===false)throw new Exception('암호화 데이터 오류');$n=substr($b,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$x=sodium_crypto_secretbox_open(substr($b,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),$n,$GLOBALS['key']);if($x===false)throw new Exception('복호화 오류');return $x;}
function default_config():array{
    $rc='DBT-'.strtoupper(bin2hex(random_bytes(8)));
    return ['version'=>31,'users'=>[['id'=>1,'username'=>'admin','password_hash'=>password_hash('admin',PASSWORD_DEFAULT),'is_admin'=>1,'force_change'=>1,'created_at'=>date('Y-m-d H:i:s'),'last_login'=>null]],
            'servers'=>[],'next_user_id'=>2,'next_server_id'=>1,'recovery_hash'=>password_hash($rc,PASSWORD_DEFAULT),'recovery_code_once'=>$rc,'recovery_fails'=>0,'recovery_lock_until'=>0];
}
function loadcfg():array{
    if(!file_exists(CONFIG_FILE)){ $c=default_config(); savecfg($c); return $c; }
    $c=include CONFIG_FILE;
    if(!is_array($c)) die('DBTool 설정 파일이 손상되었습니다.');
    foreach(['users','servers'] as $k)if(!isset($c[$k])||!is_array($c[$k]))$c[$k]=[];
    return $c;
}
function savecfg(array $c):void{
    $php="<?php\nreturn ".var_export($c,true).";\n";
    file_put_contents(CONFIG_FILE,$php,LOCK_EX); @chmod(CONFIG_FILE,0600);
}
$cfg=loadcfg();

function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function checkcsrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??''))die('잘못된 요청입니다.');}
function flash(string $m):void{$_SESSION['flash']=$m;}
function takeflash():string{$x=$_SESSION['flash']??'';unset($_SESSION['flash']);return $x;}
function logged():bool{return isset($_SESSION['uid']);}
function userbyid(int $id):?array{global $cfg;foreach($cfg['users'] as $u)if((int)$u['id']===$id)return $u;return null;}
function me():?array{return logged()?userbyid((int)$_SESSION['uid']):null;}
function admin():bool{$u=me();return $u && !empty($u['is_admin']);}
function requirelogin():void{if(!logged()){header('Location:?login=1');exit;}}
function drivers():array{$x=[];if(extension_loaded('pdo_mysql'))$x['mysql']='MySQL / MariaDB';if(extension_loaded('pdo_sqlsrv'))$x['sqlsrv']='Microsoft SQL Server';return $x;}
function getserver(int $id):?array{global $cfg;foreach($cfg['servers'] as $s)if((int)$s['id']===$id)return $s;return null;}
function setserver(array $s):void{global $cfg;foreach($cfg['servers'] as $i=>$x)if((int)$x['id']===(int)$s['id']){$cfg['servers'][$i]=$s;savecfg($cfg);return;}}
function qid(string $d,string $id):string{return $d==='mysql'?'`'.str_replace('`','``',$id).'`':'['.str_replace(']',']]',$id).']';}
function safeid(string $x):bool{return (bool)preg_match('/^[A-Za-z0-9_$-]{1,128}$/',$x);}
function dbpdo(array $s):PDO{
    $pass=dec($s['password_enc']);$d=$s['driver'];$host=str_replace([";","\0"],'',$s['host']);$port=trim($s['port']??'');$name=str_replace([";","\0"],'',$s['database_name']??'');
    if($d==='mysql')$dsn='mysql:host='.$host.($port!==''?';port='.(int)$port:'').($name!==''?';dbname='.$name:'').';charset=utf8mb4';
    elseif($d==='sqlsrv')$dsn='sqlsrv:Server='.$host.($port!==''?','.(int)$port:'').($name!==''?';Database='.$name:'');
    else throw new Exception('지원하지 않는 DB 드라이버입니다.');
    return new PDO($dsn,$s['user'],$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
}
function dbswitch(array &$s,string $dbname):void{$s['database_name']=$dbname;setserver($s);}

$loginError='';$error='';$showRecovery=($cfg['recovery_code_once']??'')!=='';

if(isset($_GET['logout'])){session_destroy();header('Location:?login=1');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
    $a=$_POST['action']??'';
    if($a==='login'){
        checkcsrf();$name=trim($_POST['username']??'');$pw=$_POST['password']??'';$found=null;
        foreach($cfg['users'] as $u)if(strtolower($u['username'])===strtolower($name)){$found=$u;break;}
        if($found&&password_verify($pw,$found['password_hash'])){session_regenerate_id(true);$_SESSION['uid']=$found['id'];foreach($cfg['users'] as &$u)if($u['id']===$found['id'])$u['last_login']=date('Y-m-d H:i:s');unset($u);savecfg($cfg);header('Location:?');exit;}
        $loginError='아이디 또는 비밀번호가 올바르지 않습니다.';
    } else {
        requirelogin(); checkcsrf();
        try{
            if($a==='ack_recovery'){ $cfg['recovery_code_once']='';savecfg($cfg);header('Location:?');exit; }
            if(!admin() && in_array($a,['add_user','edit_user','delete_user','admin_change_password','add_server','edit_server','delete_server'],true))throw new Exception('관리자만 사용할 수 있습니다.');
            if($a==='change_my_password'||$a==='admin_change_password'){
                $id=$a==='admin_change_password'?(int)$_POST['id']:(int)$_SESSION['uid'];$n=$_POST['new']??'';$n2=$_POST['new2']??'';
                if(strlen($n)<8)throw new Exception('비밀번호는 8자 이상이어야 합니다.');if($n!==$n2)throw new Exception('비밀번호가 일치하지 않습니다.');
                foreach($cfg['users'] as &$u)if((int)$u['id']===$id){$u['password_hash']=password_hash($n,PASSWORD_DEFAULT);$u['force_change']=0;}unset($u);savecfg($cfg);flash('비밀번호가 변경되었습니다.');header('Location:?view=users');exit;
            }
            if($a==='add_user'||$a==='edit_user'){
                $id=(int)($_POST['id']??0);$name=trim($_POST['username']??'');$pw=$_POST['password']??'';$adm=!empty($_POST['is_admin'])?1:0;
                if(!preg_match('/^[A-Za-z0-9_.-]{3,64}$/',$name))throw new Exception('아이디는 영문/숫자/._- 3~64자로 입력하세요.');
                foreach($cfg['users'] as $u)if(strtolower($u['username'])===strtolower($name)&&(int)$u['id']!==$id)throw new Exception('이미 존재하는 아이디입니다.');
                if($a==='add_user'){if(strlen($pw)<8)throw new Exception('비밀번호는 8자 이상이어야 합니다.');$cfg['users'][]=['id'=>$cfg['next_user_id']++,'username'=>$name,'password_hash'=>password_hash($pw,PASSWORD_DEFAULT),'is_admin'=>$adm,'force_change'=>1,'created_at'=>date('Y-m-d H:i:s'),'last_login'=>null];}
                else{foreach($cfg['users'] as &$u)if((int)$u['id']===$id){if($id===$_SESSION['uid']&&$adm===0)throw new Exception('현재 로그인 계정의 관리자 권한은 제거할 수 없습니다.');$u['username']=$name;$u['is_admin']=$adm;if($pw!==''){if(strlen($pw)<8)throw new Exception('비밀번호는 8자 이상이어야 합니다.');$u['password_hash']=password_hash($pw,PASSWORD_DEFAULT);$u['force_change']=0;}}unset($u);}
                savecfg($cfg);flash('웹 로그인 사용자가 저장되었습니다.');header('Location:?view=users');exit;
            }
            if($a==='delete_user'){ $id=(int)$_POST['id'];if($id===$_SESSION['uid'])throw new Exception('현재 로그인 계정은 삭제할 수 없습니다.');if(count($cfg['users'])<=1)throw new Exception('마지막 사용자는 삭제할 수 없습니다.');$cfg['users']=array_values(array_filter($cfg['users'],fn($u)=>(int)$u['id']!==$id));savecfg($cfg);flash('사용자가 삭제되었습니다.');header('Location:?view=users');exit;}
            if($a==='add_server'||$a==='edit_server'){
                $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$d=$_POST['driver']??'';$host=trim($_POST['host']??'');$port=trim($_POST['port']??'');$user=trim($_POST['user']??'');$pw=$_POST['password']??'';$db=trim($_POST['database_name']??'');
                if($name===''||$host===''||$user===''||!isset(drivers()[$d]))throw new Exception('DB 서버 정보를 확인하세요.');
                if($a==='add_server'){if($pw==='')throw new Exception('DB 비밀번호를 입력하세요.');$cfg['servers'][]=['id'=>$cfg['next_server_id']++,'name'=>$name,'driver'=>$d,'host'=>$host,'port'=>$port,'user'=>$user,'password_enc'=>enc($pw),'database_name'=>$db,'created_at'=>date('Y-m-d H:i:s')];}
                else{$s=getserver($id);if(!$s)throw new Exception('서버를 찾을 수 없습니다.');$s['name']=$name;$s['driver']=$d;$s['host']=$host;$s['port']=$port;$s['user']=$user;$s['database_name']=$db;if($pw!=='')$s['password_enc']=enc($pw);setserver($s);}
                savecfg($cfg);flash('DB 서버가 저장되었습니다.');header('Location:?view=servers');exit;
            }
            if($a==='delete_server'){ $id=(int)$_POST['id'];$cfg['servers']=array_values(array_filter($cfg['servers'],fn($s)=>(int)$s['id']!==$id));savecfg($cfg);flash('DB 서버가 삭제되었습니다.');header('Location:?view=servers');exit; }
            $sid=(int)($_POST['server_id']??0);$s=getserver($sid);if(!$s)throw new Exception('DB 서버를 찾을 수 없습니다.');$pdo=dbpdo($s);
            if($a==='select_db'){ $db=trim($_POST['db_name']??'');if($db==='')throw new Exception('DB를 선택하세요.');dbswitch($s,$db);flash('기본 데이터베이스를 변경했습니다.');header('Location:?server='.$sid.'&view=dashboard');exit; }
            if($a==='create_db'||$a==='drop_db'){
                $n=trim($_POST['db_name']??'');if(!safeid($n))throw new Exception('데이터베이스 이름이 올바르지 않습니다.');
                $pdo->exec(($a==='create_db'?'CREATE DATABASE ':'DROP DATABASE ').qid($s['driver'],$n));flash('데이터베이스 작업이 완료되었습니다.');header('Location:?server='.$sid.'&view=databases');exit;
            }
            if($a==='create_table'||$a==='drop_table'||$a==='truncate_table'){
                $t=trim($_POST['table']??'');if(!safeid($t))throw new Exception('테이블 이름 오류.');
                if($a==='create_table'){$cols=trim($_POST['columns']??'');if($cols==='')throw new Exception('컬럼 정의를 입력하세요.');$pdo->exec('CREATE TABLE '.qid($s['driver'],$t).' ('.$cols.')');}
                elseif($a==='drop_table')$pdo->exec('DROP TABLE '.qid($s['driver'],$t));else $pdo->exec($s['driver']==='mysql'?'TRUNCATE TABLE '.qid('mysql',$t):'DELETE FROM '.qid('sqlsrv',$t));
                flash('테이블 작업이 완료되었습니다.');header('Location:?server='.$sid.'&view=tables');exit;
            }
            if($a==='update_row'){
                $t=$_POST['table']??'';$pk=$_POST['pk']??'';$old=$_POST['pk_value']??'';$set=$_POST['set']??[];if(!safeid($t)||!safeid($pk)||!is_array($set))throw new Exception('행 수정값 오류.');
                $parts=[];$vals=[];foreach($set as $k=>$v){if(!safeid($k)||$k===$pk)continue;$parts[]=qid($s['driver'],$k).'=?';$vals[]=$v;}if(!$parts)throw new Exception('수정할 컬럼이 없습니다.');$vals[]=$old;$pdo->prepare('UPDATE '.qid($s['driver'],$t).' SET '.implode(',',$parts).' WHERE '.qid($s['driver'],$pk).'=?')->execute($vals);flash('행이 수정되었습니다.');header('Location:?server='.$sid.'&view=table&table='.urlencode($t));exit;
            }
            if($a==='delete_row'){
                $t=$_POST['table']??'';$pk=$_POST['pk']??'';$v=$_POST['pk_value']??'';if(!safeid($t)||!safeid($pk))throw new Exception('PK 정보가 올바르지 않습니다.');$pdo->prepare('DELETE FROM '.qid($s['driver'],$t).' WHERE '.qid($s['driver'],$pk).'=?')->execute([$v]);flash('행이 삭제되었습니다.');header('Location:?server='.$sid.'&view=table&table='.urlencode($t));exit;
            }
            if($a==='sql'){$_SESSION['sql_result']=run_sql($pdo,$_POST['sql']??'');header('Location:?server='.$sid.'&view=sql');exit;}
            if(str_starts_with($a,'event_')){
                if($s['driver']!=='mysql')throw new Exception('이벤트/스케줄러 UI는 MySQL/MariaDB에서 지원됩니다.');
                $n=trim($_POST['event_name']??'');if(!safeid($n))throw new Exception('이벤트 이름 오류.');
                if($a==='event_create'){$schedule=trim($_POST['schedule']??'');$body=trim($_POST['body']??'');if($schedule===''||$body==='')throw new Exception('스케줄과 SQL을 입력하세요.');$pdo->exec('CREATE EVENT '.qid('mysql',$n).' ON SCHEDULE '.$schedule.' DO '.$body);}
                elseif($a==='event_alter'){$schedule=trim($_POST['schedule']??'');$body=trim($_POST['body']??'');$pdo->exec('ALTER EVENT '.qid('mysql',$n).' ON SCHEDULE '.$schedule.' DO '.$body);}
                elseif($a==='event_delete')$pdo->exec('DROP EVENT '.qid('mysql',$n));
                elseif($a==='scheduler')$pdo->exec("SET GLOBAL event_scheduler=".($_POST['scheduler']==='ON'?'ON':'OFF'));
                flash('이벤트 작업이 완료되었습니다.');header('Location:?server='.$sid.'&view=events');exit;
            }
            if(str_starts_with($a,'trigger_')){
                if($s['driver']!=='mysql')throw new Exception('트리거 UI는 MySQL/MariaDB에서 지원됩니다.');
                $n=trim($_POST['trigger_name']??'');if(!safeid($n))throw new Exception('트리거 이름 오류.');
                if($a==='trigger_create'){$t=trim($_POST['trigger_table']??'');$tim=$_POST['timing']??'BEFORE';$ev=$_POST['trigger_event']??'INSERT';$body=trim($_POST['body']??'');if(!safeid($t)||!in_array($tim,['BEFORE','AFTER'],true)||!in_array($ev,['INSERT','UPDATE','DELETE'],true)||$body==='')throw new Exception('트리거 정보를 확인하세요.');$pdo->exec('CREATE TRIGGER '.qid('mysql',$n).' '.$tim.' '.$ev.' ON '.qid('mysql',$t).' FOR EACH ROW '.$body);}
                elseif($a==='trigger_delete')$pdo->exec('DROP TRIGGER '.qid('mysql',$n));
                elseif($a==='trigger_alter')throw new Exception('MySQL/MariaDB는 트리거 본문을 ALTER로 수정할 수 없습니다. 삭제 후 다시 생성하세요.');
                flash('트리거 작업이 완료되었습니다.');header('Location:?server='.$sid.'&view=triggers');exit;
            }
            if($a==='kill_session'){ $id=(int)$_POST['session_id'];if($s['driver']==='mysql')$pdo->exec('KILL '.$id);else $pdo->exec('KILL '.$id);flash('세션 종료 요청이 완료되었습니다.');header('Location:?server='.$sid.'&view=sessions');exit; }
            if(str_starts_with($a,'dbuser_')){
                $un=trim($_POST['db_username']??'');$newpw=$_POST['db_password']??'';$host=$_POST['db_host']??'%';
                if($un===''||strlen($un)>128)throw new Exception('DB 사용자 이름을 확인하세요.');
                if($s['driver']==='mysql'){
                    if($a==='dbuser_create'){if(strlen($newpw)<8)throw new Exception('DB 사용자 비밀번호는 8자 이상을 권장합니다.');$pdo->exec("CREATE USER ".$pdo->quote($un)."@".$pdo->quote($host)." IDENTIFIED BY ".$pdo->quote($newpw));}
                    elseif($a==='dbuser_drop'){$pdo->exec("DROP USER ".$pdo->quote($un)."@".$pdo->quote($host));}
                    elseif($a==='dbuser_alter'){if($newpw==='')throw new Exception('새 비밀번호를 입력하세요.');$pdo->exec("ALTER USER ".$pdo->quote($un)."@".$pdo->quote($host)." IDENTIFIED BY ".$pdo->quote($newpw));}
                    elseif($a==='dbuser_grant'){$priv=$_POST['privileges']??'SELECT';if(!preg_match('/^[A-Z ,]+$/',$priv))throw new Exception('권한 형식 오류.');$target=$_POST['grant_target']??'*.*';if(!preg_match('/^[A-Za-z0-9_$*.-]+\\.[A-Za-z0-9_$*-]+$/',$target))throw new Exception('권한 대상 형식 오류.');$pdo->exec('GRANT '.$priv.' ON '.$target.' TO '.$pdo->quote($un).'@'.$pdo->quote($host));$pdo->exec('FLUSH PRIVILEGES');}
                } else {
                    if($a==='dbuser_create'){$pdo->exec('CREATE LOGIN '.qid('sqlsrv',$un).' WITH PASSWORD='.$pdo->quote($newpw));}
                    elseif($a==='dbuser_drop')$pdo->exec('DROP LOGIN '.qid('sqlsrv',$un));
                    elseif($a==='dbuser_alter')$pdo->exec('ALTER LOGIN '.qid('sqlsrv',$un).' WITH PASSWORD='.$pdo->quote($newpw));
                    else throw new Exception('SQL Server 권한 변경은 SQL 실행 메뉴에서 T-SQL을 사용하세요.');
                }
                flash('DB 사용자 계정 작업이 완료되었습니다.');header('Location:?server='.$sid.'&view=users_db');exit;
            }
        }catch(Throwable $e){$error=$e->getMessage();}
    }
}
function run_sql(PDO $pdo,string $sql):array{
    if(trim($sql)==='')throw new Exception('SQL을 입력하세요.');
    $st=$pdo->prepare($sql);$st->execute();if($st->columnCount()>0)return $st->fetchAll();return [['결과'=>'실행 완료','영향 행'=>$st->rowCount()]];
}
if(!logged()){
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DBTool 로그인</title><style>body{margin:0;background:#eef1f5;font-family:Arial,"Noto Sans KR",sans-serif;display:grid;place-items:center;min-height:100vh}.box{width:min(410px,calc(100% - 30px));background:#fff;padding:30px;border-radius:18px;box-shadow:0 15px 50px #0002}label{display:block;font-weight:bold;margin:12px 0 5px}input{width:100%;padding:11px;box-sizing:border-box;border:1px solid #ddd;border-radius:8px}button{width:100%;margin-top:16px;padding:11px;border:0;border-radius:8px;background:#111827;color:#fff;font-weight:bold}.err{background:#fee2e2;color:#991b1b;padding:10px;border-radius:8px}
