function translateNode(node,dict){{
  if(node.nodeType===Node.TEXT_NODE){{const raw=node.nodeValue, t=raw.trim(); if(t && dict[t]) node.nodeValue=raw.replace(t,dict[t]); return;}}
  if(node.nodeType!==Node.ELEMENT_NODE) return;
  if(node.id==='langSelect') return;
  for(const a of ['placeholder','title','aria-label']){{if(node.hasAttribute(a)){{const v=node.getAttribute(a);if(dict[v])node.setAttribute(a,dict[v]);}}}}
  for(const c of node.childNodes) translateNode(c,dict);
}}
function setLang(lang){{
 localStorage.setItem('dbtool_lang',lang);
 const dict=lang==='en'?DBT_LANGS.en:{};
 document.documentElement.lang=lang==='en'?'en':'ko';
 document.title=lang==='en'?'DBTool v3.1':'DBTool v3.1';
 translateNode(document.body,dict);
 document.querySelectorAll('#langSelect').forEach(x=>x.value=lang);
}}
(function(){{const l=localStorage.getItem('dbtool_lang')||'ko'; window.setLang=setLang; setLang(l);}})();
