$me=me();$view=$_GET['view']??'dashboard';$sid=(int)($_GET['server']??0);$cur=$sid?getserver($sid):null;$flash=takeflash();$result=$_SESSION['sql_result']??null;unset($_SESSION['sql_result']);
$servers=$cfg['servers'];$users=$cfg['users'];$dbs=[];$tables=[];$columns=[];$rows=[];$events=[];$triggers=[];$sessions=[];$stats=[];$dbusers=[];$searchResults=[];$scheduler=null;
if($cur){
 try{
  $pdo=dbpdo($cur);
  if($cur['driver']==='mysql')$dbs=array_column($pdo->query('SHOW DATABASES')->fetchAll(PDO::FETCH_NUM),0);
  else $dbs=array_column($pdo->query("SELECT name FROM sys.databases WHERE state=0 ORDER BY name")->fetchAll(PDO::FETCH_NUM),0);
  if($cur['database_name']!==''){
   if($cur['driver']==='mysql')$tables=array_column($pdo->query("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME")->fetchAll(PDO::FETCH_NUM),0);
   else $tables=array_column($pdo->query("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_TYPE='BASE TABLE' ORDER BY TABLE_NAME")->fetchAll(PDO::FETCH_NUM),0);
  }
  $tn=$_GET['table']??'';
  if($tn!==''&&in_array($tn,$tables,true)){
   if($cur['driver']==='mysql'){$q=$pdo->prepare("SELECT COLUMN_NAME,DATA_TYPE,IS_NULLABLE,COLUMN_KEY,COLUMN_DEFAULT FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION");$q->execute([$tn]);$columns=$q->fetchAll();}
   else{$q=$pdo->prepare("SELECT COLUMN_NAME,DATA_TYPE,IS_NULLABLE,'' AS COLUMN_KEY,COLUMN_DEFAULT FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME=? ORDER BY ORDINAL_POSITION");$q->execute([$tn]);$columns=$q->fetchAll();}
   if($view==='table')$rows=$pdo->query('SELECT * FROM '.qid($cur['driver'],$tn).($cur['driver']==='mysql'?' LIMIT 100':' OFFSET 0 ROWS FETCH NEXT 100 ROWS ONLY'))->fetchAll();
  }
  if($view==='events'&&$cur['driver']==='mysql'){$events=$pdo->query("SELECT EVENT_NAME,EVENT_TYPE,EXECUTE_AT,INTERVAL_VALUE,INTERVAL_FIELD,STATUS,EVENT_DEFINITION,LAST_EXECUTED FROM INFORMATION_SCHEMA.EVENTS WHERE EVENT_SCHEMA=DATABASE() ORDER BY EVENT_NAME")->fetchAll();$scheduler=$pdo->query("SHOW VARIABLES LIKE 'event_scheduler'")->fetch()['Value']??'';}
  if($view==='triggers'&&$cur['driver']==='mysql')$triggers=$pdo->query("SELECT TRIGGER_NAME,EVENT_MANIPULATION,EVENT_OBJECT_TABLE,ACTION_TIMING,ACTION_STATEMENT,CREATED FROM INFORMATION_SCHEMA.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() ORDER BY TRIGGER_NAME")->fetchAll();
  if($view==='sessions')$sessions=$cur['driver']==='mysql'?$pdo->query("SHOW FULL PROCESSLIST")->fetchAll():$pdo->query("SELECT session_id,login_name,status,host_name,program_name,last_request_start_time,last_request_end_time FROM sys.dm_exec_sessions WHERE is_user_process=1 ORDER BY session_id")->fetchAll();
  if($view==='stats')$stats=$cur['driver']==='mysql'?$pdo->query("SELECT TABLE_NAME,TABLE_ROWS,DATA_LENGTH,INDEX_LENGTH,(DATA_LENGTH+INDEX_LENGTH) TOTAL_BYTES FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TOTAL_BYTES DESC")->fetchAll():$pdo->query("SELECT t.name TABLE_NAME,SUM(p.rows) TABLE_ROWS,SUM(a.total_pages)*8 TOTAL_KB FROM sys.tables t JOIN sys.indexes i ON t.object_id=i.object_id JOIN sys.partitions p ON i.object_id=p.object_id AND i.index_id=p.index_id JOIN sys.allocation_units a ON p.partition_id=a.container_id GROUP BY t.name ORDER BY TOTAL_KB DESC")->fetchAll();
  if($view==='users_db'){
   if($cur['driver']==='mysql')$dbusers=$pdo->query("SELECT User,Host,plugin FROM mysql.user ORDER BY User,Host")->fetchAll();
   else $dbusers=$pdo->query("SELECT name,type_desc,authentication_type_desc,create_date,modify_date FROM sys.database_principals WHERE type IN('S','U','G') AND name NOT IN('dbo','guest','INFORMATION_SCHEMA','sys') ORDER BY name")->fetchAll();
  }
  if($view==='search'&&isset($_GET['q'])&&$_GET['q']!==''){
   $needle=(string)$_GET['q'];foreach($tables as $t){try{
    if($cur['driver']==='mysql')$cs=$pdo->query('SHOW COLUMNS FROM '.qid('mysql',$t))->fetchAll();else{$qq=$pdo->prepare("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME=? ORDER BY ORDINAL_POSITION");$qq->execute([$t]);$cs=$qq->fetchAll();}
    $names=[];foreach($cs as $c)$names[]=$c['Field']??$c['COLUMN_NAME'];$parts=[];foreach($names as $n)$parts[]='CAST('.qid($cur['driver'],$n).' AS CHAR) LIKE ?';$st=$pdo->prepare('SELECT * FROM '.qid($cur['driver'],$t).' WHERE '.implode(' OR ',$parts).' LIMIT 20');$st->execute(array_fill(0,count($names),'%'.$needle.'%'));foreach($st->fetchAll() as $rr)$searchResults[]=['table'=>$t,'row'=>$rr];
   }catch(Throwable $ignore){}}
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
